/** 将业务节点数组组装成 BusinessInventory。 */
export function toBusinessInventory(nodes: BusinessNode[]): BusinessInventory {
  const map: Record<string, BusinessNode> = {};
  for (const n of nodes) map[n.id] = n;
  return {
    schemaVersion: 1,
    generatedAt: "2026-07-27T00:00:00Z",
    nodes: map,
  };
}
